"""Release B5: optional "Generated by StockBill" line under each invoice page."""

import pymupdf
from rest_framework.test import APIClient, APITestCase

from billing.models import BusinessProfile
from billing.pdf_engine import STOCKBILL_CREDIT_TEXT, build_invoice_a5_pdf
from billing.tests import test_pdf as pdf_tests  # module import: avoids re-collecting its TestCases here
from billing.tests.test_pdf import InvoicePdfLayoutHelpers


class StockBillCreditTests(InvoicePdfLayoutHelpers, APITestCase):
    setUpTestData = pdf_tests.InvoicePdfGenerationTests.__dict__["setUpTestData"]

    def render(self, enabled, lines=None):
        BusinessProfile.objects.filter(pk=self.profile.pk).update(show_stockbill_credit=enabled)
        return pymupdf.open("pdf", build_invoice_a5_pdf(self.invoice, lines=lines))

    def test_off_by_default(self):
        self.assertFalse(BusinessProfile._meta.get_field("show_stockbill_credit").default)
        doc = pymupdf.open("pdf", build_invoice_a5_pdf(self.invoice))
        self.assertNotIn(STOCKBILL_CREDIT_TEXT, doc[0].get_text())

    def test_line_is_printed_below_the_footer_on_every_page_when_on(self):
        doc = self.render(True, lines=self.make_lines(27))
        self.assertGreater(len(doc), 1)
        for page in doc:
            spans = [s for b in page.get_text("dict")["blocks"] for l in b.get("lines", []) for s in l["spans"]]
            credit = [s for s in spans if s["text"] == STOCKBILL_CREDIT_TEXT]
            self.assertEqual(len(credit), 1)
            self.assertAlmostEqual(credit[0]["size"], 6 * 0.98, delta=0.1)
            signatory = next(w for w in page.get_text("words") if w[4] == "Signatory")
            border_bottom = signatory[3] + 3  # the invoice border sits just under "Authorised Signatory"
            self.assertGreater(credit[0]["bbox"][1], border_bottom)  # entirely below the footer
            self.assertNotEqual(credit[0]["color"], 0)  # grey, not black

    def test_line_is_absent_when_off(self):
        for page in self.render(False, lines=self.make_lines(27)):
            self.assertNotIn(STOCKBILL_CREDIT_TEXT, page.get_text())

    def test_pagination_is_unchanged(self):
        lines = self.make_lines(27)
        off = self.render(False, lines=lines)
        on = self.render(True, lines=lines)
        self.assertEqual(len(on), len(off))
        self.assertEqual(self.item_numbers_per_page(on), self.item_numbers_per_page(off))
        self.assert_rows_clear_of_footer(on)

    def test_admin_can_switch_it_on(self):
        from django.contrib.auth import get_user_model

        admin = get_user_model().objects.create_user(username="credit-admin", password="Pass-12345!", role="admin")
        client = APIClient()
        client.force_authenticate(admin)
        response = client.patch("/api/business-profile/", {"show_stockbill_credit": True}, format="json")
        self.assertEqual(response.status_code, 200)
        self.assertTrue(response.data["show_stockbill_credit"])
        self.assertTrue(BusinessProfile.objects.get(pk=self.profile.pk).show_stockbill_credit)
